#!/usr/bin/env python3
"""Fetch the full order listing and the customers behind qualifying orders.

Raw responses are saved under RAW_DIR so the arithmetic can be re-run and
checked without calling the service again. Every failed request is repeated.
"""
import http.client
import json
import os
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

BASE = "http://localhost:8080"
RAW_DIR = "/tmp/recon/raw"
LOG_PATH = "/tmp/recon/events.log"
MAX_ATTEMPTS = 40
ORDER_FIELDS = {"id", "customer_id", "status", "placed_at", "amount_cents"}
WINDOW_START = datetime(2025, 3, 1, tzinfo=timezone.utc)
WINDOW_END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive


def log(message):
    with open(LOG_PATH, "a", encoding="utf-8") as fh:
        fh.write(time.strftime("%H:%M:%S ") + message + "\n")


def backoff(attempt):
    return min(0.5 * 2 ** attempt, 15.0)


def retry_hint(headers, text):
    """Seconds the service asked us to wait: Retry-After header, else a JSON field, else None."""
    for name, value in headers.items():
        if name.lower() == "retry-after":
            try:
                return float(value)
            except ValueError:
                pass
    try:
        body = json.loads(text)
    except ValueError:
        return None
    if isinstance(body, dict):
        for key, value in body.items():
            if "retry" in key.lower() and isinstance(value, (int, float)):
                return float(value)
    return None


def parse_utc(text):
    value = text[:-1] + "+00:00" if text.endswith("Z") else text
    moment = datetime.fromisoformat(value)
    if moment.tzinfo is None:
        raise ValueError("timestamp without offset: " + text)
    return moment.astimezone(timezone.utc)


class Api:
    def __init__(self):
        self.token = None
        self.token_issues = 0
        self.calls = 0
        self.retries = 0

    def _send(self, method, path, authenticated):
        headers = {"Accept": "application/json"}
        if authenticated:
            headers["Authorization"] = "Bearer " + self.token
        req = urllib.request.Request(
            BASE + path,
            data=b"" if method == "POST" else None,
            method=method,
            headers=headers,
        )
        self.calls += 1
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, resp.headers, resp.read().decode("utf-8", "replace")
        except urllib.error.HTTPError as err:
            return err.code, err.headers, err.read().decode("utf-8", "replace")

    def refresh_token(self):
        data = self.get_json(
            "POST",
            "/token",
            lambda d: isinstance(d, dict) and isinstance(d.get("token"), str),
            authenticated=False,
        )
        self.token = data["token"]
        self.token_issues += 1
        log(f"token issued #{self.token_issues}")

    def get_json(self, method, path, check, authenticated=True, not_found_ok=False):
        """Return parsed JSON for a 200 that passes check(). Repeat the same request on any failure."""
        not_found = 0
        for attempt in range(1, MAX_ATTEMPTS + 1):
            if authenticated and self.token is None:
                self.refresh_token()
            try:
                status, headers, text = self._send(method, path, authenticated)
            except (OSError, http.client.HTTPException) as exc:
                self.retries += 1
                log(f"{method} {path} #{attempt}: transport error {exc!r}")
                time.sleep(backoff(attempt))
                continue

            if status == 200:
                try:
                    data = json.loads(text)
                except ValueError:
                    data = None
                if data is not None and check(data):
                    return data
                self.retries += 1
                log(f"{method} {path} #{attempt}: 200 with unexpected body {text[:200]!r}")
                time.sleep(backoff(attempt))
                continue

            if status == 404 and not_found_ok:
                not_found += 1
                log(f"{method} {path} #{attempt}: 404")
                if not_found == 3:
                    return None
                time.sleep(1)
                continue

            self.retries += 1
            if status in (401, 403):
                log(f"{method} {path} #{attempt}: HTTP {status} {text[:200]!r}; discarding token")
                self.token = None
                continue
            if status == 429:
                hint = retry_hint(headers, text)
                log(f"{method} {path} #{attempt}: 429 hint={hint} headers={list(headers.items())} body={text[:200]!r}")
                time.sleep(hint if hint is not None else backoff(attempt))
                continue
            log(f"{method} {path} #{attempt}: HTTP {status} {text[:200]!r}")
            time.sleep(backoff(attempt))
        raise RuntimeError(f"{method} {path} failed {MAX_ATTEMPTS} times; giving up")


def valid_page(data, page_no):
    return (
        isinstance(data, dict)
        and data.get("page") == page_no
        and isinstance(data.get("total_pages"), int)
        and isinstance(data.get("items"), list)
        and "next" in data
        and all(isinstance(item, dict) and ORDER_FIELDS <= set(item) for item in data["items"])
    )


def valid_customer(data, customer_id):
    return (
        isinstance(data, dict)
        and data.get("id") == customer_id
        and "region" in data
        and isinstance(data.get("discount_pct"), (int, float))
    )


def main():
    os.makedirs(RAW_DIR, exist_ok=True)
    open(LOG_PATH, "w", encoding="utf-8").close()  # fresh event log for this run
    api = Api()

    pages = {}
    path = "/orders?page=1"
    for page_no in range(1, 1001):
        data = api.get_json("GET", path, lambda d: valid_page(d, page_no))
        pages[page_no] = data
        print(f"page {page_no}: {len(data['items'])} rows, total_pages={data['total_pages']}, next={data['next']}")
        if data["next"] is None:
            break
        path = data["next"]

    total_pages = pages[1]["total_pages"]
    if len(pages) != total_pages or any(p["total_pages"] != total_pages for p in pages.values()):
        raise SystemExit(f"fetched {len(pages)} pages but total_pages reports {total_pages}")
    with open(os.path.join(RAW_DIR, "pages.json"), "w", encoding="utf-8") as fh:
        json.dump(pages, fh)

    # Customers are needed only for distinct orders that can qualify.
    needed = set()
    for page in pages.values():
        for item in page["items"]:
            if item["status"] == "shipped" and WINDOW_START <= parse_utc(item["placed_at"]) < WINDOW_END:
                needed.add(item["customer_id"])

    customers = {}
    for customer_id in sorted(needed):
        customers[customer_id] = api.get_json(
            "GET",
            f"/customers/{customer_id}",
            lambda d: valid_customer(d, customer_id),
            not_found_ok=True,
        )
    with open(os.path.join(RAW_DIR, "customers.json"), "w", encoding="utf-8") as fh:
        json.dump(customers, fh)

    unknown = [cid for cid, rec in customers.items() if rec is None]
    print(f"customers fetched: {len(customers)}; unknown ids: {unknown}")
    print(f"tokens issued: {api.token_issues}; HTTP calls: {api.calls}; retried attempts: {api.retries}")


if __name__ == "__main__":
    main()

